-- Grace (profileID=7) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Grace phrasings

SELECT p.argumentID, p.phrasingID, 7, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 7
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 7 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=7 AND targArgID IN (100,124,125,126,127,128,129,130,142,143,144,154,161,237,242,244,245,313,320,322,428,560,598,604,785,844,849,902,903,964,975,1385,1386,1387,1438,1440,1645);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 7
SET pe.active = o.acceptance
WHERE pe.profileID = 7;

SELECT 'Done: endorsements for profileID=7' AS status;